const $=id=>document.getElementById(id);
let user=null,authMode='login',avatarDraft='',authToken='',localAccounts=false,tourStep=0;
const bookIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 6.5C9 4.8 5.5 4.3 2.5 5v14c3-.7 6.5-.2 9.5 1.5 3-1.7 6.5-2.2 9.5-1.5V5c-3-.7-6.5-.2-9.5 1.5Z"/><path d="M12 6.5v14M5.5 8.5l3.5 1M5.5 12l3.5 1M15 9.5l3.5-1M15 13l3.5-1"/></svg>';
const personIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 20v-2a7 7 0 0 1 14 0v2"/></svg>';
const arrowIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>';
const shieldIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg>';
const mount=document.createElement('div');
mount.innerHTML=`<div class="account-toolbar" aria-label="指南与个人账号">
  <button id="guide-launch" type="button" aria-haspopup="dialog"><span class="account-guide-symbol">${bookIcon}</span><span>新手指南</span></button>
  <button id="account-launch" class="account-launch" type="button" aria-haspopup="dialog"><span class="avatar-mini" id="toolbar-avatar">访</span><span class="toolbar-identity"><span id="toolbar-name">登录 / 注册</span><small id="toolbar-state">访客浏览</small></span><svg class="account-chevron" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button>
</div>
<dialog id="auth-dialog" class="account-dialog account-polished" aria-labelledby="auth-title">
  <header class="account-dialog-header"><div class="account-heading"><span class="account-heading-icon">${personIcon}</span><div><span class="account-eyebrow">TIDEFLOW / ACCOUNT</span><h2 id="auth-title">欢迎回到潮汐</h2></div></div><button class="close" type="button" aria-label="关闭登录">×</button></header>
  <p class="account-intro">登录本机账号，继续你的海上风电仿真。资料保存在本机，仿真工作区由本机用户共享。</p>
  <div class="auth-tabs"><button id="auth-login-tab" class="active" type="button">登录</button><button id="auth-register-tab" type="button">创建账号</button></div>
  <form id="account-auth-form"><label for="account-name">账号</label><input id="account-name" autocomplete="username" pattern="[A-Za-z0-9_]{3,32}" required maxlength="32" placeholder="3—32 位字母、数字或下划线"><div id="register-name-wrap" hidden><label for="register-name">昵称</label><input id="register-name" maxlength="30" autocomplete="nickname"></div><label for="account-password">密码</label><input id="account-password" type="password" autocomplete="current-password" required minlength="8" maxlength="128" placeholder="至少 8 位"><div id="confirm-password-wrap" hidden><label for="confirm-password">确认密码</label><input id="confirm-password" type="password" autocomplete="new-password" maxlength="128"></div><p class="form-status" id="auth-status" role="status"></p><button class="primary account-submit" type="submit" id="auth-submit">登录工作空间 →</button></form>
  <p class="account-footnote">无需登录即可浏览模型与已有结果；运行新工况及调用 AI 需要本机账号。当前不提供邮箱验证或密码找回。</p>
</dialog>
<dialog id="profile-dialog" class="account-dialog profile-dialog account-polished" aria-labelledby="profile-title">
  <header class="account-dialog-header"><div class="account-heading"><span class="account-heading-icon">${personIcon}</span><div><span class="account-eyebrow">PERSONAL / PROFILE</span><h2 id="profile-title">个人中心</h2></div></div><button class="close" type="button" aria-label="关闭个人资料">×</button></header>
  <form id="profile-form"><div class="profile-layout">
    <aside class="profile-identity"><div class="avatar-large" id="profile-avatar"></div><h3 id="profile-display-name"></h3><span class="profile-signed-state">本机账号 · 已登录</span><p class="profile-workspace-label">YOUR TIDEFLOW WORKSPACE</p><p class="profile-identity-note">从模型到结果，<br>记录每一次工程探索。</p><div class="avatar-editor"><button id="avatar-upload" type="button" class="avatar-upload">更换头像 ↗</button><input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden><button id="avatar-remove" type="button" class="quiet">移除头像</button></div></aside>
    <section class="profile-main" aria-labelledby="profile-details-title"><h3 id="profile-details-title">你的个人资料</h3><p class="account-intro">为工作空间添加你的身份信息。</p>
      <div class="profile-grid"><div><label for="profile-name">昵称</label><input id="profile-name" maxlength="30" required autocomplete="nickname"></div><div><label for="profile-account">账号</label><input id="profile-account" readonly></div><div><label for="profile-affiliation">学校 / 单位</label><input id="profile-affiliation" maxlength="80" autocomplete="organization" placeholder="填写学校或所属单位"></div><div><label for="profile-specialty">专业 / 研究方向</label><input id="profile-specialty" maxlength="60" placeholder="你的专业领域"></div></div>
      <div class="profile-wide-field"><label for="profile-email">联系邮箱（选填）</label><input id="profile-email" type="email" maxlength="120" autocomplete="email" placeholder="name@example.com"></div><div class="profile-wide-field"><label for="profile-bio">个人简介</label><textarea id="profile-bio" maxlength="300" rows="2" placeholder="例如：关注海上风电与浮式平台动力学。"></textarea></div>
      <p class="profile-privacy-note">${shieldIcon}<span>资料保存在本机。头像支持 PNG / JPEG / WebP，最大 5 MB。</span></p><p class="form-status" id="profile-status" role="status"></p><div class="profile-actions"><button class="secondary" type="button" id="account-logout">退出登录</button><button class="primary" type="submit" id="profile-save">保存资料 →</button></div>
    </section>
  </div></form>
</dialog>
<dialog id="tour-dialog" class="account-dialog tour-dialog account-polished" aria-labelledby="tour-heading">
  <header class="account-dialog-header"><div class="account-heading"><span class="account-heading-icon">${bookIcon}</span><div><span class="account-eyebrow">GETTING STARTED</span><h2 id="tour-heading">新手指南</h2></div></div><button class="close" type="button" aria-label="关闭新手指南">×</button></header>
  <nav class="tour-progress" id="tour-progress" aria-label="指南步骤"></nav><div class="tour-layout"><section class="tour-main" aria-live="polite"><span class="tour-number" id="tour-number"></span><h2 id="tour-title"></h2><p id="tour-description"></p><ol id="tour-checklist"></ol><button id="tour-page" type="button" class="text-link">打开对应页面 ↗</button></section>
    <aside class="tour-reference"><span class="account-eyebrow">REFERENCE MODEL / 参考模型</span><div class="tour-reference-visual"><svg viewBox="0 0 280 210" fill="none" aria-label="浮式风机结构示意" role="img"><g stroke="#9bbcc2" stroke-width=".65" opacity=".45"><path d="M0 145h280M0 165h280M0 185h280M30 210l90-80M90 210l40-80M190 210l-40-80M250 210l-90-80"/></g><g stroke="#397b88" stroke-width="1.7" stroke-linejoin="round"><path d="m135 58-4 91h14l-5-91M138 55l-9-39 5-11 8 48M140 57l39 4 8 8-44-7M136 59l-30 31-10 1 36-36" fill="#dbe9eb"/><circle cx="138" cy="56" r="4" fill="#f5fbfb"/><path d="m138 144-48 24 50 21 49-24-51-21Z" fill="#e4eef0"/><path d="m90 168 50 20 49-23M138 144l2 44M90 156v23M138 135v22M189 153v24"/><ellipse cx="90" cy="155" rx="8" ry="3" fill="#cfE1e5"/><path d="M82 155v23c0 4 16 4 16 0v-23M130 136v23c0 4 16 4 16 0v-23M181 154v23c0 4 16 4 16 0v-23" fill="#d4e5e8"/><ellipse cx="138" cy="136" rx="8" ry="3"/><ellipse cx="189" cy="154" rx="8" ry="3"/><path d="m84 179-33 22M190 178l41 23M140 190v19" stroke-dasharray="3 3"/></g><g stroke="#8eb4bc" stroke-width=".8"><path d="M142 41h57M147 111h52M200 145h26"/><circle cx="201" cy="41" r="2"/><circle cx="201" cy="111" r="2"/><circle cx="228" cy="145" r="2"/></g><g fill="#648e98" font-family="Consolas,monospace" font-size="8"><text x="207" y="44">ROTOR</text><text x="207" y="114">TOWER</text><text x="211" y="137">OC4</text></g></svg></div><h3 class="tour-reference-title">NREL 5 MW / OC4</h3><p class="tour-reference-note">从风轮、塔架到浮式平台，<br>建立完整的结构认知。</p><div class="tour-reference-specs"><div><small>额定功率</small><strong>5 MW</strong></div><div><small>平台形式</small><strong>半潜式 · OC4</strong></div></div></aside>
  </div><footer class="tour-footer"><label><input type="checkbox" id="tour-auto" checked> 首次登录时显示指南</label><div><button id="tour-prev" type="button" class="secondary">上一步</button><button id="tour-next" type="button" class="primary">下一步 →</button></div></footer>
</dialog>`;
document.body.append(mount);
document.querySelector('.side-bottom').insertAdjacentHTML('afterbegin','<button id="side-account">登录 / 个人资料 <span>↗</span></button><button id="side-guide">新手指南 <span>↗</span></button>');
for(const d of mount.querySelectorAll('dialog')){d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});}
function status(id,message,error=false){$(id).textContent=message;$(id).classList.toggle('error',error);}
async function accountRequest(path,data){if(!localAccounts)throw Error('账号功能需要本机服务。请启动新版 server.py 后刷新。');const response=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-Run-Token':authToken}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'操作未完成，请重试。');return result;}
function paintAvatar(element,person,override){element.replaceChildren();const value=override===undefined?person?.avatar:override;if(value){const img=document.createElement('img');img.src=value;img.alt='个人头像';element.append(img);}else element.textContent=(person?.display_name||'访').slice(0,1);}
function updateIdentity(){paintAvatar($('toolbar-avatar'),user);$('toolbar-name').textContent=user?.display_name||'登录 / 注册';$('toolbar-state').textContent=user?'本机账号':'访客浏览';$('profile-display-name').textContent=user?.display_name||'';$('account-launch').setAttribute('aria-label',user?'个人资料：'+user.display_name:'登录或注册账号');$('side-account').firstChild.textContent=user?'个人资料 · '+user.display_name:'登录 / 个人资料';document.body.dataset.signedIn=String(!!user);window.dispatchEvent(new CustomEvent('tideflow:account',{detail:{signedIn:!!user}}));}
function authView(mode){authMode=mode;const register=mode==='register';$('auth-title').textContent=register?'创建你的潮汐账号':'欢迎回到潮汐';$('register-name-wrap').hidden=!register;$('confirm-password-wrap').hidden=!register;$('register-name').required=register;$('confirm-password').required=register;$('account-password').autocomplete=register?'new-password':'current-password';$('auth-submit').textContent=register?'创建账号并登录 →':'登录工作空间 →';$('auth-login-tab').classList.toggle('active',!register);$('auth-register-tab').classList.toggle('active',register);status('auth-status','');}
function openAuth(){if(!$('auth-dialog').open){authView('login');$('account-password').value='';$('confirm-password').value='';$('auth-dialog').showModal();}}
function openProfile(){if(!user)return openAuth();$('profile-name').value=user.display_name;$('profile-account').value=user.account;$('profile-affiliation').value=user.affiliation;$('profile-specialty').value=user.specialty;$('profile-email').value=user.email;$('profile-bio').value=user.bio;avatarDraft=user.avatar;paintAvatar($('profile-avatar'),user);status('profile-status','');$('profile-dialog').showModal();}
$('account-launch').onclick=openProfile;$('side-account').onclick=openProfile;
$('auth-login-tab').onclick=()=>authView('login');$('auth-register-tab').onclick=()=>authView('register');
$('avatar-upload').onclick=()=>$('avatar-file').click();
$('account-auth-form').onsubmit=async e=>{e.preventDefault();if(authMode==='register'&&$('account-password').value!==$('confirm-password').value)return status('auth-status','两次输入的密码不一致。',true);$('auth-submit').disabled=true;status('auth-status','正在处理…');try{const result=await accountRequest('/api/account/'+(authMode==='register'?'register':'login'),{account:$('account-name').value.trim(),password:$('account-password').value,display_name:$('register-name').value.trim()||$('account-name').value.trim()});user=result.user;updateIdentity();$('account-password').value='';$('confirm-password').value='';$('auth-dialog').close();let seen=false;try{seen=localStorage.getItem('tideflow-guide-seen-'+user.id)==='true'||localStorage.getItem('tideflow-guide-auto')==='false';}catch{}if(!seen)openTour();}catch(error){status('auth-status',error.message,true);}finally{$('auth-submit').disabled=false;}};
$('avatar-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('请选择不超过 5 MB 的 PNG、JPEG 或 WebP。');const image=await createImageBitmap(file);if(!image.width||!image.height)throw Error('图片无法读取。');const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const context=canvas.getContext('2d');context.fillStyle='#e5f2f2';context.fillRect(0,0,256,256);const side=Math.min(image.width,image.height);context.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,256,256);image.close();avatarDraft=canvas.toDataURL('image/jpeg',.88);paintAvatar($('profile-avatar'),user,avatarDraft);status('profile-status','头像预览已更新，保存资料后生效。');}catch(error){status('profile-status',error.message,true);}finally{e.target.value='';}};
$('avatar-remove').onclick=()=>{avatarDraft='';paintAvatar($('profile-avatar'),user,'');};
$('profile-form').onsubmit=async e=>{e.preventDefault();$('profile-save').disabled=true;try{const data={display_name:$('profile-name').value,affiliation:$('profile-affiliation').value,specialty:$('profile-specialty').value,email:$('profile-email').value,bio:$('profile-bio').value,avatar:avatarDraft};user=(await accountRequest('/api/account/profile',data)).user;updateIdentity();status('profile-status','资料已保存到本机。');}catch(error){status('profile-status',error.message,true);}finally{$('profile-save').disabled=false;}};
$('account-logout').onclick=async()=>{try{await accountRequest('/api/account/logout',{});user=null;updateIdentity();$('profile-dialog').close();$('ai-disconnect').click();window.dispatchEvent(new CustomEvent('tideflow:navigate',{detail:'home'}));}catch(error){status('profile-status',error.message,true);}};
const tour=[{title:'先认识固定参考模型',page:'model',text:'本项目围绕 NREL 5 MW / OC4 半潜式风机展开，先理解风轮、平台与系泊的关系。',items:['点击模型上的三个部件标记查看说明。','工程原理页可了解各耦合模块的输入与响应。','结构示意图用于理解组成，计算参数以官方输入为准。']},{title:'定义一组可复现的工况',page:'configure',text:'填写风速、波浪、时长、分析起点与随机种子。先用默认短时工况熟悉流程。',items:['规则波使用 H / T；JONSWAP 使用 Hs / Tp。','检查分析起点小于总时长，保存对照变量。','登录本机账号后提交真实 OpenFAST；耗时取决于时长与算力。']},{title:'检查日志，再看结果',page:'records',text:'运行完成只是开始。保留原始输入与输出，检查报错和启动过渡。',items:['在运行与日志页查看原文和诊断依据。','失败或取消的工况不作为完整有效结果。','分析起点需要结合时序判断，不自动代表稳态。']},{title:'比较、解释与导出',page:'analysis',text:'最多勾选四个已完成工况对比，再导出带来源与窗口说明的报告。',items:['优先一次只改变一个变量，统一分析窗口。','图表与统计来自真实输出，模型图片不是仿真动画。','AI 为可配置选项；没有服务账号也能使用规则解释与导出。']}];
const tourLabels=['认识模型','配置工况','检查运行','分析与导出'];
const tourItemTitles=[['认识关键部件','了解耦合关系','确认模型来源'],['选择波浪类型','保留工况参数','提交仿真运行'],['查看运行日志','确认工况状态','判断分析窗口'],['建立可比工况','追溯结果来源','解释与导出报告']];
function renderTour(){const step=tour[tourStep];$('tour-progress').replaceChildren(...tour.map((_,i)=>{const b=document.createElement('button');b.type='button';b.className=i===tourStep?'active':'';b.setAttribute('aria-label','指南第 '+(i+1)+' 步：'+tourLabels[i]);if(i===tourStep)b.setAttribute('aria-current','step');const number=document.createElement('span');number.className='progress-number';number.textContent='0'+(i+1);const label=document.createElement('span');label.className='progress-label';label.textContent=tourLabels[i];b.append(number,label);b.onclick=()=>{tourStep=i;renderTour();};return b;}));$('tour-number').textContent='STEP 0'+(tourStep+1)+' / 04';$('tour-title').textContent=step.title;$('tour-description').textContent=step.text;$('tour-checklist').replaceChildren(...step.items.map((text,i)=>{const li=document.createElement('li');const number=document.createElement('span');number.className='tour-item-index';number.textContent='0'+(i+1);const copy=document.createElement('div');const title=document.createElement('strong');title.textContent=tourItemTitles[tourStep][i];const detail=document.createElement('span');detail.className='tour-item-detail';detail.textContent=text;copy.append(title,detail);li.append(number,copy);li.insertAdjacentHTML('beforeend',arrowIcon);return li;}));$('tour-prev').disabled=tourStep===0;$('tour-next').textContent=tourStep===3?'完成指南 ✓':'下一步 →';}
function openTour(){tourStep=0;renderTour();try{$('tour-auto').checked=localStorage.getItem('tideflow-guide-auto')!=='false';}catch{}$('tour-dialog').showModal();}
$('guide-launch').onclick=openTour;$('side-guide').onclick=openTour;$('help-open').onclick=openTour;
$('tour-prev').onclick=()=>{if(tourStep>0){tourStep--;renderTour();}};$('tour-next').onclick=()=>{if(tourStep<3){tourStep++;renderTour();}else{try{if(user)localStorage.setItem('tideflow-guide-seen-'+user.id,'true');localStorage.setItem('tideflow-guide-auto',String($('tour-auto').checked));}catch{}$('tour-dialog').close();}};
$('tour-page').onclick=()=>{window.dispatchEvent(new CustomEvent('tideflow:navigate',{detail:tour[tourStep].page}));$('tour-dialog').close();};
window.addEventListener('tideflow:login-required',openAuth);
async function init(){try{const health=await fetch('/api/health').then(r=>r.json());authToken=health.token||'';const response=await fetch('/api/account');if(!response.ok)throw Error();const data=await response.json();localAccounts=true;user=data.user;updateIdentity();}catch{status('auth-status','账号功能需启动新版本机服务；可继续浏览已有算例。');}}
updateIdentity();init();
